import { ControlPosition } from 'maplibre-gl';
import * as maplibregl from 'maplibre-gl';
import { MapOptions } from 'maplibre-gl';

/**
 * Drop-in replacement for `maplibregl.Map`.
 *
 * Use it exactly like plain MapLibre GL JS's `Map` — same options, same
 * methods, same events — plus one required addition, `apiKey`. See
 * {@link NeshanMapOptions} for all SDK-specific options.
 *
 * On construction it transparently:
 *  - registers the `nsh://` tile protocol (once per page, shared by all maps
 *    on that page) so encoded, gzip-compressed vector tiles are decoded and
 *    the API key attached automatically on every tile request,
 *  - replaces MapLibre's default attribution with one that includes the
 *    Neshan/OpenStreetMap brand entry,
 *  - replaces MapLibre's default logo with the Neshan brand logo control.
 *
 * @example
 * ```ts
 * import maplibregl from '@neshan/maplibre-sdk';
 * import '@neshan/maplibre-sdk/style.css';
 *
 * const map = new maplibregl.Map({
 *   container: 'map',
 *   style,
 *   center: [51.389, 35.6892],
 *   zoom: 12,
 *   apiKey: 'YOUR_API_KEY',
 * });
 * ```
 *
 * @throws {Error} if `apiKey` is missing.
 */
declare class Map_2 extends maplibregl.Map {
    constructor(options: NeshanMapOptions);
}
export { Map_2 as Map }

/**
 * Options for constructing a {@link Map}.
 *
 * Extends MapLibre's own `MapOptions` one-for-one — every option you'd pass
 * to `maplibregl.Map` still works here (`container`, `style`, `center`,
 * `zoom`, etc.) — plus a small set of SDK-specific additions below.
 *
 * @example
 * ```ts
 * const map = new maplibregl.Map({
 *   container: 'map',
 *   style,
 *   center: [51.389, 35.6892],
 *   zoom: 12,
 *   apiKey: 'YOUR_API_KEY',
 * });
 * ```
 */
export declare interface NeshanMapOptions extends MapOptions {
    /**
     * Your client-facing API key. Required.
     *
     * Sent as `?key=...` on every map tile request. Without it, tile requests
     * will be rejected by the tile server.
     */
    apiKey?: string;
    /**
     * @deprecated Ignored. RTL text (Arabic/Persian/Hebrew) is always shaped
     * correctly by MapLibre itself; there is nothing to enable or disable.
     */
    rtl?: boolean | RtlOptions;
    /**
     * Where to place the attribution control (the "©Neshan ©OpenStreetMap"
     * text) on the map.
     *
     * @default 'bottom-left'
     */
    logoPosition?: ControlPosition;
    /**
     * Where to place the Neshan brand logo control on the map.
     *
     * @default 'bottom-right'
     */
    copyRightPosition?: ControlPosition;
}

/**
 * @deprecated MapLibre v6 shapes Arabic/Persian/Hebrew text natively, so no
 * RTL plugin is loaded and these options are ignored. Kept only so existing
 * code that passes them still compiles.
 */
export declare interface RtlOptions {
    lazy?: boolean;
    url?: string;
}

declare const sdk: Omit<typeof maplibregl, "Map"> & {
    Map: typeof Map_2;
};
export default sdk;

export { }
